    channelIds: [10000],
    description: "An alert definition for ansible test",
    groupBies: ["entity_id"],
    label: "test-alert-definition",
    ruleCriteria: {
        rules: [{
            aggregateFunction: "avg",
            dimensionFilters: [{
                dimensionLabel: "node_type",
                operator: "eq",
                value: "primary",
