    image: "linode/arch",
    region: "ca-east",
    type: "g6-dedicated-2",
});
const fooRdns = new linode.Rdns("fooRdns", {
    address: fooInstance.ipAddress,
    rdns: pulumi.interpolate`${fooInstance.ipAddress}.nip.io`,
});
```
